import java.nio.file.*;import java.io.*;public class NativeAuraTextureProbe {public static void main(String[]args)throws Exception {Class<?> c=Class.forName("zombie.core.textures.ImageData");int count=0;try(var files=Files.list(Path.of(args[0]))){for(Path p:files.filter(x->x.getFileName().toString().matches("(?:ExtremeHeat|TauntAura).*\\.png")&&x.toString().endsWith(".png")).toList()){Object image;try(var input=Files.newInputStream(p)){image=c.getConstructor(InputStream.class,boolean.class).newInstance(input,false);}int w=(Integer)c.getMethod("getWidth").invoke(image),h=(Integer)c.getMethod("getHeight").invoke(image);boolean taunt=p.getFileName().toString().startsWith("TauntAura"),flame=p.getFileName().toString().contains("flame");if(w!=(taunt?128:flame?32:64)||h!=(taunt?256:flame?32:p.getFileName().toString().contains("smoke")?64:128))throw new AssertionError(p+" "+w+"x"+h);if(c.getMethod("getData").invoke(image)==null)throw new AssertionError("missing decoded pixels");c.getMethod("dispose").invoke(image);count++;}}if(count!=226)throw new AssertionError("texture count "+count);System.out.println("PASS "+count+" original-size aura and approved colour-copy PNGs decode through native B42 ImageData (GPU appearance untested)");}}